INSERT INTO Language_en_US(Tag,Text) VALUES
 ('TXT_KEY_CWC3_COVENANT_CIV','The Candlekeeper''s Covenant'),
 ('TXT_KEY_CWC3_COVENANT_SHORT','Candlekeeper''s Covenant'),
 ('TXT_KEY_CWC3_COVENANT_ADJECTIVE','Covenant'),
 ('TXT_KEY_CWC3_COVENANT_LEADER','High Keeper Seraphine'),
 ('TXT_KEY_CWC3_COVENANT_TRAIT','The Names We Carry'),
 ('TXT_KEY_CWC3_COVENANT_TRAIT_HELP','Permanently destroyed foreign major cities grant one Lost Flame each, up to 12. Each Flame provides +1 [ICON_CULTURE] Culture in the current Capital; every three provide +1 [ICON_RESEARCH] Science. Captures grant nothing. Cities founded by any Covenant are excluded.'),
 ('TXT_KEY_CWC3_COVENANT_CIV_PEDIA','No Flame Shall Be Forgotten. The Candlekeepers preserve the names of lost settlements in an underground archive. Each memory becomes a flame, sustaining a patient civilization devoted to Culture, Science and defensive warfare.'),
 ('TXT_KEY_CWC3_COVENANT_STRATEGY','Protect the Capital and build Halls of Remembrance. Destruction anywhere in the world accumulates permanent Lost Flames without requiring contact or visibility. Capturing cities grants no Flames. Culture / Science focus; complexity 4/5.'),
 ('TXT_KEY_CWC3_COVENANT_LEADER_PEDIA','High Keeper Seraphine is an elderly woman with white hair and calm, bright eyes. Her dark ceremonial robes bear silver embroidery. She carries a lantern containing an ancient flame through an underground archive illuminated by thousands of candles. Patient, reserved and reflective, she protects historical knowledge.'),
 ('TXT_KEY_CWC3_COVENANT_UNIT','Vigil Keeper'),
 ('TXT_KEY_CWC3_COVENANT_UNIT_HELP','Replaces the active Pikeman. Eternal Vigil: +1 Sight, and +15% Combat Strength only when defending in friendly territory. Both benefits persist through normal upgrades.'),
 ('TXT_KEY_CWC3_COVENANT_UNIT_PEDIA','Vigil Keepers defend the archives and carry the light into the uncertain world beyond.'),
 ('TXT_KEY_CWC3_COVENANT_UNIT_STRATEGY','Retains active CP Pikeman stats, costs, resource requirements, maintenance and upgrade path. Friendly territory uses the native engine rule, including qualifying Open Borders. No offensive bonus.'),
 ('TXT_KEY_CWC3_COVENANT_PROMOTION','Eternal Vigil'),
 ('TXT_KEY_CWC3_COVENANT_PROMOTION_HELP','+1 Sight permanently. +15% defense in native friendly territory; no attack bonus. Persists through upgrades.'),
 ('TXT_KEY_CWC3_COVENANT_DEFENSE','Eternal Vigil: Friendly Defense'),
 ('TXT_KEY_CWC3_COVENANT_DEFENSE_HELP','+15% defense only. Active while the Eternal Vigil veteran stands in native friendly territory.'),
 ('TXT_KEY_CWC3_COVENANT_HALL','Hall of Remembrance'),
 ('TXT_KEY_CWC3_COVENANT_HALL_HELP','Replaces the active Temple, preserving all its normal effects. +1 permanent [ICON_CULTURE] Culture. Covenant-owned Halls add +1 [ICON_RESEARCH] Science at 3 Lost Flames and +2 at 9.'),
 ('TXT_KEY_CWC3_COVENANT_HALL_PEDIA','Every lost city becomes a memory. Every forgotten name becomes a flame. The Halls preserve both for generations yet to come.'),
 ('TXT_KEY_CWC3_COVENANT_HALL_STRATEGY','Build in every city. Each Hall adds +1 Culture and conditional Science at 3 and 9 global Lost Flames, including in the Capital.'),
 ('TXT_KEY_CWC3_COVENANT_DUMMY','Covenant Memory'),
 ('TXT_KEY_CWC3_COVENANT_DUMMY_HELP','Internal recurring yield controller. Cannot be constructed or purchased.'),
 ('TXT_KEY_CWC3_COVENANT_GREETING_1','Welcome, traveler. Tell me your name. I would like to remember it.'),
 ('TXT_KEY_CWC3_COVENANT_WAR_1','We sought to preserve your history. You have forced us to become part of it.'),
 ('TXT_KEY_CWC3_COVENANT_ATTACKED_1','Another war... another thousand names. Must the world always learn through suffering?'),
 ('TXT_KEY_CWC3_COVENANT_DEFEAT_1','Do not mourn us. Remember us.'),
 ('TXT_KEY_CWC3_COVENANT_PEACE_1','Let us preserve what remains, together.'),
 ('TXT_KEY_CWC3_COVENANT_FRIENDLY_1','Your name is welcome in these halls.'),
 ('TXT_KEY_CWC3_COVENANT_NEUTRAL_1','The archive is listening.'),
 ('TXT_KEY_CWC3_COVENANT_HOSTILE_1','What memory will you leave behind?'),
 ('TXT_KEY_CWC3_COVENANT_TRADE_1','Let this agreement be remembered.'),
 ('TXT_KEY_CWC3_COVENANT_FALLBACK_1','We shall remember your words.'),
 ('TXT_KEY_CWC3_COVENANT_DAWN','Eternal High Keeper Seraphine, Guardian of the Last Light, your people await your guidance.[NEWLINE][NEWLINE]Since the beginning of civilization, countless kingdoms have risen beneath the sun.[NEWLINE][NEWLINE]Their rulers constructed monuments. Their armies marched across continents. Their scholars recorded the achievements of their people.[NEWLINE][NEWLINE]Yet time has claimed them all.[NEWLINE][NEWLINE]Cities have fallen. Empires have vanished. Entire peoples have disappeared from the pages of history.[NEWLINE][NEWLINE]But your ancestors refused to forget.[NEWLINE][NEWLINE]Within the sacred halls of the Covenant, every lost city became a memory. Every forgotten name became a flame.[NEWLINE][NEWLINE]Now, the world stands once more upon the threshold of a new age.[NEWLINE][NEWLINE]Build your cities. Protect your archives. Preserve the knowledge of those who came before.[NEWLINE][NEWLINE]Will your civilization become the final guardian of history?[NEWLINE][NEWLINE]Or will its own flame eventually fade into darkness?'),
 ('TXT_KEY_CWC3_COVENANT_CITY_1','Last Light'),
 ('TXT_KEY_CWC3_COVENANT_CITY_2','Ember Archive'),
 ('TXT_KEY_CWC3_COVENANT_CITY_3','Quiet Vigil'),
