INSERT INTO Diplomacy_Responses(LeaderType,ResponseType,Response,Bias) SELECT DISTINCT 'LEADER_CWC3_COVENANT_SERAPHINE',N.ResponseType,'TXT_KEY_CWC3_COVENANT_FALLBACK_%',1 FROM Diplomacy_Responses N WHERE N.LeaderType='LEADER_WASHINGTON' AND NOT EXISTS (SELECT 1 FROM Diplomacy_Responses C WHERE C.LeaderType='LEADER_CWC3_COVENANT_SERAPHINE' AND C.ResponseType=N.ResponseType);
